function imageUrlOf(value) {
  if (!value) return null;
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) return imageUrlOf(value[0]);
  if (typeof value === 'object') return value.url || value.contentUrl || null;
  return null;
